function solve(n, edges) {
  const key = Array(n).fill(Infinity)
  const masuk = Array(n).fill(false)
  key[0] = 0
  let total = 0
  for (let k = 0; k < n; k++) {
    // EXTRACT-MIN: simpul di luar tree dengan key terkecil.
    let u = -1
    for (let i = 0; i < n; i++) {
      if (!masuk[i] && (u === -1 || key[i] < key[u])) u = i
    }
    masuk[u] = true
    total += key[u]
    for (const [a, b, w] of edges) {
      if (a === u && !masuk[b] && w < key[b]) key[b] = w
      if (b === u && !masuk[a] && w < key[a]) key[a] = w
    }
  }
  return total
}
